+/// Drive a libsql future to completion without an async runtime.
+///
+/// `libsql` core's local-database futures execute their sqlite calls
+/// inline while being polled and never suspend, so a bare poll loop is
+/// sufficient — the tools crate is synchronous by contract and must not
+/// grow a tokio dependency for this. (Verified: create/insert/query
+/// round-trip outside any runtime.)
+pub fn block_on<F: std::future::IntoFuture>(f: F) -> F::Output {
+    use std::sync::Arc;
+    use std::task::{Context, Poll, Wake, Waker};
+    struct Flag(AtomicBool);
+    impl Wake for Flag {
+        fn wake(self: Arc<Self>) {
+            self.0.store(true, Ordering::Relaxed);
+        }
+    }
+    let flag = Arc::new(Flag(AtomicBool::new(false)));
+    let waker = Waker::from(flag.clone());
+    let mut cx = Context::from_waker(&waker);
+    let mut fut = Box::pin(f.into_future());
+    loop {
+        if let Poll::Ready(v) = fut.as_mut().poll(&mut cx) {
+            return v;
+        }
+        flag.0.store(false, Ordering::Relaxed);
+        while !flag.0.load(Ordering::Relaxed) {
+            std::thread::yield_now();
+        }
+    }
+}
